# Prefill (compute-bound) check: FLOPs vs peak
import math
P=27e9; L,d=64,4096
def prefill_tps(FLOPS, seq, batch=1, eff=0.4):
    flops = batch*seq*(2*P + 4*L*d*seq)   # matmul + attention
    return flops/eff/(FLOPS*1e12)
peaks={"V100":125,"A100":312,"4090":82.6}  # TFLOPS fp16 tensor
for s in [2048,8192]:
    print(f"prefill seq={s}:")
    for g,f in peaks.items():
        print(f"  {g}: {prefill_tps(f,s)*1e3:7.1f} ms  ({s/prefill_tps(f,s)/1e3:.0f} tok/s)")

